  .main-box .sitehead .m-dec>.mhead,
  .main-box .sitehead .m-worlds .mhead{
    color:#fff;
    font-family:Inter,sans-serif;
    font-weight:600;
  }
  .main-box .sitehead .mgroup.lit>.mhead,
  .main-box .sitehead .mgroup:hover>.mhead,
  .main-box .sitehead .mgroup:focus-within>.mhead{
    color:#f6c177;
  }
}
@media (max-width: 900px){
  .main-box .product-sheet .menu-close,
  .main-box .msheet:not(.product-sheet) .menu-close{
    top:105px;
  }
}
/* Abby desktop menu and footer optical alignment */
@media (min-width: 901px){
  .main-box .sitehead .mgroup:hover>.mhead,
  .main-box .sitehead .mgroup:focus-within>.mhead,
  .main-box .sitehead .mgroup.lit>.mhead,
  .main-box .sitehead .mgroup.lit:not(.open)>.mhead{
    color:#f6c177!important;
  }
  .main-box .footer-identity .footer-logo{
    width:104px;
    height:90px;
  }
  .main-box .footer-social a[aria-label="Facebook"] svg{
    width:20px;
    height:20px;
  }
}
@media (max-width: 600px){
  .main-box .footer-social a[aria-label="Facebook"] svg{
    width:13px;
    height:13px;
  }
}
/* User-supplied mobile dock icon set */
@media (max-width: 600px){
  .main-box .halo-tab .halo-icon{
    top:50%;
    fill:none!important;
    stroke:none!important;
    background-color:currentColor;
    -webkit-mask-position:center;
    mask-position:center;
    -webkit-mask-repeat:no-repeat;
    mask-repeat:no-repeat;
