    <!-- JAVASCRIPT -->
    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // Search Toggle
            const searchContainer = document.getElementById('searchContainer');
            const searchToggle = document.getElementById('searchToggle');
            const searchInput = document.getElementById('searchInput');
            const searchIcon = document.getElementById('searchIcon');
            const closeIcon = document.getElementById('closeIcon');
            let isSearchOpen = false;

            searchToggle.addEventListener('click', function(e) {
                e.stopPropagation();
                isSearchOpen = !isSearchOpen;
                searchContainer.classList.toggle('is-open', isSearchOpen);
                searchIcon.style.display = isSearchOpen ? 'none' : 'block';
                closeIcon.style.display = isSearchOpen ? 'block' : 'none';
                searchToggle.setAttribute('aria-expanded', isSearchOpen);
                searchToggle.setAttribute('aria-label', isSearchOpen ? 'Close search' : 'Open search');
                if (isSearchOpen) {
                    setTimeout(() => searchInput.focus(), 100);
                }
            });

            // Close search when clicking outside
            document.addEventListener('click', function(e) {
                if (isSearchOpen && !searchContainer.contains(e.target)) {
                    isSearchOpen = false;
                    searchContainer.classList.remove('is-open');
                    searchIcon.style.display = 'block';
                    closeIcon.style.display = 'none';
                    searchToggle.setAttribute('aria-expanded', 'false');
                    searchToggle.setAttribute('aria-label', 'Open search');
                }
            });

            // Close search on Escape key
            document.addEventListener('keydown', function(e) {
                if (e.key === 'Escape' && isSearchOpen) {
                    isSearchOpen = false;
                    searchContainer.classList.remove('is-open');
                    searchIcon.style.display = 'block';
                    closeIcon.style.display = 'none';
                    searchToggle.setAttribute('aria-expanded', 'false');
                    searchToggle.setAttribute('aria-label', 'Open search');
                }
            });

            // Header Scroll Effect
            const header = document.querySelector('.sitehead');
            window.addEventListener('scroll', function() {
                if (window.pageYOffset > 50) {
                    header.classList.add('scrolled');
                } else {
                    header.classList.remove('scrolled');
                }
            });

            // Footer Accordions
            const accordionToggles = document.querySelectorAll('.footer-accordion-toggle');
            
            accordionToggles.forEach(function(toggle) {
                toggle.addEventListener('click', function() {
                    const accordion = this.parentElement;
                    const isOpen = accordion.classList.contains('is-open');
                    const panel = accordion.querySelector('.footer-accordion-panel');
                    
                    accordion.classList.toggle('is-open');
                    this.setAttribute('aria-expanded', !isOpen);
                    panel.setAttribute('aria-hidden', isOpen);
                });
            });

            // Mega dropdown hover effects
            const mgroups = document.querySelectorAll('.mgroup');
            mgroups.forEach(function(mgroup) {
                mgroup.addEventListener('mouseenter', function() {
                    this.classList.add('lit');
                });
                
                mgroup.addEventListener('mouseleave', function() {
                    this.classList.remove('lit');
                });
            });
        });
    </script>



